export const primaryStories={math:['Pip brings one round snack.','Cut it into four equal bites.','Give Pip two bites. Two of four is half!','Two bites for Pip. Two bites for a friend. Fair shares!'],science:['Pip’s little cart is waiting.','A small push starts it moving.','A bigger push changes its motion more.','A heavier cart is harder to speed up with the same push.'],coding:['Pip needs to cross the river.','Say “step” once. Pip moves one stone.','Repeat the step. Pip moves again.','Three repeats make three steps. Pip is across!'],cs:['Pip has a postcard for a friend.','The first helper reads the address.','The next helper passes the parcel along.','The parcel reaches Pip’s friend. Three links carried it!'],engineering:['Pip’s rover wants to reach the flag.','Look: the rover is still far away.','Move closer, then look again.','A smaller move helps the rover reach the flag.'],logic:['Three friends bring their stars.','Put the stars together. There are twelve!','Give one to each friend, then repeat.','Each friend gets four stars. The fair share is four!']};
export function storyVisual(subject,step,value,playing){const navy='#173454',blue='#2264e5',amber='#f5b64c';let drawing='';const pip=(x,y)=>`<g transform="translate(${x} ${y})"><rect x="-23" y="-24" width="46" height="48" rx="18" fill="${amber}" stroke="#b97913" stroke-width="2"/><circle cx="-8" cy="-5" r="3"/><circle cx="8" cy="-5" r="3"/><path d="M-8 7q8 9 16 0" stroke="${navy}" stroke-width="2" fill="none"/></g>`;
if(subject==='math'){drawing=`${pip(100,120)}<g transform="translate(320 110)">${Array.from({length:4},(_,i)=>{const a=i*Math.PI/2,b=(i+1)*Math.PI/2,x=step>=2&&i<2?12:0;return `<path d="M${x} 0L${x+85*Math.cos(a)} ${85*Math.sin(a)}A85 85 0 0 1 ${x+85*Math.cos(b)} ${85*Math.sin(b)}Z" fill="${step>=2&&i<2?blue:amber}" stroke="#fffaf0" stroke-width="${step?6:0}"/>`}).join('')}</g>${step>=2?'<text x="455" y="120" font-size="35" fill="#2264e5">½</text>':''}`}
if(subject==='science'){const x=160+step*55;drawing=`<path d="M60 175H550" stroke="#c4a56e" stroke-width="3"/>${pip(70,125)}<g style="transition:transform .8s" transform="translate(${x} 100)"><rect width="100" height="50" rx="10" fill="${blue}"/><circle cx="20" cy="60" r="15" fill="${navy}"/><circle cx="80" cy="60" r="15" fill="${navy}"/>${step===3?'<rect x="20" y="-30" width="60" height="30" rx="5" fill="#f5b64c"/>':''}</g>${step?`<path d="M110 80h${step===2?110:50}l-15-10m15 10-15 10" stroke="${amber}" stroke-width="8" fill="none"/>`:''}`}
if(subject==='coding'){drawing=`<path d="M80 190q80-30 140 0t140 0t140 0" stroke="#b6d1f2" stroke-width="35" fill="none"/>${[0,1,2,3].map(i=>`<ellipse cx="${100+i*130}" cy="160" rx="40" ry="14" fill="${i<=step?blue:'#b7c9dd'}"/><text x="${100+i*130}" y="215" text-anchor="middle" font-size="20" fill="${navy}">${i}</text>`).join('')}${pip(100+step*130,115)}`}
if(subject==='cs'){drawing=`<path d="M70 120H530" stroke="#c4a56e" stroke-width="4" stroke-dasharray="8 7"/>${[70,220,370,530].map((x,i)=>`${pip(x,120)}<text x="${x}" y="180" font-size="17" text-anchor="middle" fill="${navy}">${['Pip','Helper','Helper','Friend'][i]}</text>`).join('')}<g transform="translate(${70+step*153} 55)"><rect x="-22" y="-15" width="44" height="30" rx="4" fill="${blue}"/><path d="M-20-12 0 3 20-12" stroke="white" fill="none"/></g>`}
if(subject==='engineering'){drawing=`<path d="M60 180H540" stroke="#c4a56e" stroke-width="3"/><path d="M490 50v130m0-130h45l-13 15 13 15h-45" fill="${amber}" stroke="#a96718"/>${pip([100,220,360,470][step],145)}<path d="M${[125,245,385,495][step]} 145H480" stroke="${blue}" stroke-width="3" stroke-dasharray="7 6"/><text x="300" y="220" font-size="21" text-anchor="middle" fill="${navy}">${['Find the flag','Look, then move','Look again','Arrived!'][step]}</text>`}
if(subject==='logic'){const piles=step===0?[3,3,6]:step===1?[0,12,0]:step===2?[2,2,2]:[4,4,4];drawing=[140,300,460].map((x,i)=>`${pip(x,185)}${Array.from({length:piles[i]},(_,j)=>`<text x="${x-30+(j%3)*24}" y="${65+Math.floor(j/3)*25}" font-size="23" fill="${blue}">★</text>`).join('')}`).join('')}
return `<div class="visual story-visual" role="figure" aria-label="${primaryStories[subject][step]}"><svg viewBox="0 0 600 250" aria-hidden="true">${drawing}</svg><p class="visual-caption">${primaryStories[subject][step]}</p><div class="story-dots" aria-label="Frame ${step+1} of 4">${[0,1,2,3].map(i=>`<span style="background:${i===step?blue:'#d8c7aa'}"></span>`).join('')}</div></div>`}
